import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z2 } from "npm:zod@^3.25.76";
var create_post_default = defineTool3({
  name: "create_community_post",
  title: "Criar post na comunidade",
  description: "Publica uma nova postagem na comunidade do Projeta Aula em nome do usu\xE1rio autenticado.",
  inputSchema: {
    title: z2.string().trim().min(3).max(120).describe("T\xEDtulo da postagem."),
    content: z2.string().trim().min(1).max(5e3).describe("Conte\xFAdo da postagem."),
    hashtags: z2.array(z2.string().trim().min(1).max(50)).max(10).optional().describe("Hashtags sem o s\xEDmbolo #.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async ({ title, content, hashtags }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "N\xE3o autenticado" }], isError: true };
    }
    const supabase = supabaseForUser(ctx);
    const userId = ctx.getUserId();
    const { data: profile } = await supabase.from("profiles").select("full_name, role").eq("id", userId).maybeSingle();
    const { data, error } = await supabase.from("community_posts").insert({
      user_id: userId,
      title,
      content,
      hashtags: hashtags?.map((h) => h.replace(/^#/, "")) ?? [],
      user_name: profile?.full_name ?? "Usu\xE1rio",
      user_role: profile?.role ?? "aluno"
    }).select("id, title, content, hashtags, created_at").single();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    return {
      content: [{ type: "text", text: `Post criado: ${data.title}` }],
      structuredContent: { post: data }
    };
  }
});

